const data = $input.first().json;
function value(key, min, max) {
  const raw = data[key];
  if ((typeof raw !== 'number' && typeof raw !== 'string') || (typeof raw === 'string' && !/^(?:\d+(?:\.\d+)?|\.\d+)$/.test(raw.trim()))) throw new Error('Invalid ' + key);
  const n = Number(raw);
  if (!Number.isFinite(n) || n < min || n > max) throw new Error('Invalid ' + key);
  return n;
}
return [{json: {
  hours: value('hours', 0, 1000),
  rate: value('rate', 0, 10000),
  materials: value('materials', 0, 1000000),
  variation: value('variation', 0, 1000000),
  approved: data.approved === true
}}];

const input = $input.first().json;
const lines = [
  {description:'Labour', quantity:input.hours, rate:input.rate, amount:Math.round(input.hours * input.rate * 100)/100},
  {description:'Materials', quantity:1, rate:input.materials, amount:input.materials}
];
if (input.approved && input.variation > 0) lines.push({description:'Approved extra work',quantity:1,rate:input.variation,amount:input.variation});
return [{json:{
  kind:'invoice', mode:'simulation', job:'WB-1042', lines,
  subtotal:Math.round(lines.reduce((sum,line)=>sum+line.amount,0)*100)/100,
  needsDecision:input.variation > 0 && !input.approved,
  excluded:input.approved ? 0 : input.variation,
  approved:input.approved, externalAction:false
}}];
